import java.io.File;
import java.io.FileNotFoundException;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Map;
import java.util.Scanner;
import java.util.Set;
import java.util.TreeMap;

public class WordCounter {
    private static final Set<String> STOP_WORDS = new HashSet<>(Arrays.asList("the", "and", "a", "an", "or", "of", "to"));

    public static void main(String[] args) throws FileNotFoundException {
        Scanner scanner = new Scanner(new File("input.txt"));
        Map<String, Integer> wordCountMap = new TreeMap<>();
        int totalCount = 0;

        while (scanner.hasNextLine()) {
            String line = scanner.nextLine().toLowerCase().replaceAll("[^a-zA-Z ]", "");
            String[] words = line.split("\\s+");

            for (String word : words) {
                if (!STOP_WORDS.contains(word)) {
                    wordCountMap.put(word, wordCountMap.getOrDefault(word, 0) + 1);
                    totalCount++;
                }
            }
        }

        scanner.close();

        System.out.println("Total words: " + totalCount);
        System.out.println("Word count (excluding stop words): ");
        for (Map.Entry<String, Integer> entry : wordCountMap.entrySet()) {
            System.out.println(entry.getKey() + " : " + entry.getValue());
        }
    }
}
```

In this version of the program, we define a `STOP_WORDS` set that contains the words we want to exclude from the word count. Then, when we iterate over the words in the text file, we check if each word is in the `STOP_WORDS` set, and if it is, we skip it and move on to the next word.

Note that we've also simplified the code a bit by using the `getOrDefault` method of the map to increment the count of a word, rather than checking if the word is already in the map and setting its count accordingly.

